select o, k, estado from (
  select 1 as o, '1 las 17 funciones nuevas existen con su md5' as k, case when md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_personal_fijar(text,text,text,jsonb,text)'))) is not distinct from 'fc362a2894e064767cfca039fa5ed299' and md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_cuadrillas(text,jsonb,text)'))) is not distinct from '76b1eb22a370ab461f977ba38be9e994' and md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_cuadrilla_cambiar(text,jsonb,text)'))) is not distinct from '30ed5a23163f13c822c7d2393132541d' and md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_catalogos(text,text)'))) is not distinct from '5bec9cab11e11387073e5783fb23638a' and md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_catalogo_cambiar(text,jsonb,text)'))) is not distinct from 'b230fe8ad5d1944fbaf1106f51b47f68' and md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_personal_actividad(text,text,text)'))) is not distinct from '93ad0bd10c4222d4b1f24e0da0e43824' and md5(pg_get_functiondef(to_regprocedure('campo.f_persona_comercial(text)'))) is not distinct from '99af03344249f7260357528096e92829' and md5(pg_get_functiondef(to_regprocedure('campo.f_area_vigente(text)'))) is not distinct from '09ac12c5df5877b84fbce54e6d014470' and md5(pg_get_functiondef(to_regprocedure('campo.f_cuadrilla_vigente(text)'))) is not distinct from 'f38549b2c3ad1edb8a8c26c6b57e3cb7' and md5(pg_get_functiondef(to_regprocedure('campo.f_actividades_propias(text)'))) is not distinct from '0670bad6770dbb5191dc21dd560359f7' and md5(pg_get_functiondef(to_regprocedure('campo.f_cuadrilla_actividades(bigint)'))) is not distinct from '826d0065c2a0c783d498cbc88e98d6cc' and md5(pg_get_functiondef(to_regprocedure('campo.f_miembros_cuadrillas()'))) is not distinct from '07dac444b04ec2c0939c6180fec91343' and md5(pg_get_functiondef(to_regprocedure('campo.f_actividades_persona(text)'))) is not distinct from '69bc9bd73d5797b826b3e504c1d92070' and md5(pg_get_functiondef(to_regprocedure('campo.f_quien_puede(text)'))) is not distinct from '5a381a87f432b8d2a6c88ad98a13fe3c' and md5(pg_get_functiondef(to_regprocedure('campo.f_codigo_desde_nombre(text)'))) is not distinct from '797333afba14f417857b033ff0d52f08' and md5(pg_get_functiondef(to_regprocedure('campo.f_motivo_personal(text,boolean)'))) is not distinct from '4d7f94c08ca8e75bb724e21d9b93e272' and md5(pg_get_functiondef(to_regprocedure('campo.f_no_borrar_catalogo()'))) is not distinct from '740c50291aa0bb31a38f64724d6b3fd9' then 'OK' else 'FALLA' end as estado
  union all
  select 2 as o, '2 las 2 reemplazadas tienen el texto nuevo' as k, case when md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_personal(text,jsonb,text)'))) = '7028ce4016505ed5fd8ae706db91464c' and md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_historial_personal(text,jsonb,text)'))) = '639b9652575bffbe6390aa527f3d36f8' then 'OK' else 'FALLA' end as estado
  union all
  select 3 as o, '3 personal_cambiar (la de la Edge publicada) y f_formularios_personal sin cambio' as k, case when md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_personal_cambiar(text,text,text,text,text,text,text)'))) = 'c0302a7b45307215d8f780d8c78cd396' and md5(pg_get_functiondef(to_regprocedure('campo.f_formularios_personal()'))) = '283a63c1ee3fad9e5956a65f8a4644b6' then 'OK' else 'FALLA' end as estado
  union all
  select 4 as o, '4 las 5 tablas nuevas existen, con RLS y con su protección' as k, case when (select count(*) from pg_class where relrowsecurity and oid in (to_regclass('campo.areas_comercial'), to_regclass('campo.actividades'), to_regclass('campo.catalogo_eventos'), to_regclass('campo.cuadrillas'), to_regclass('campo.cuadrilla_eventos'))) = 5 and (select count(*) from pg_trigger where not tgisinternal and tgrelid in (to_regclass('campo.areas_comercial'), to_regclass('campo.actividades'), to_regclass('campo.catalogo_eventos'), to_regclass('campo.cuadrillas'), to_regclass('campo.cuadrilla_eventos'))) = 10 then 'OK' else 'FALLA' end as estado
  union all
  select 5 as o, '5 semilla: las 4 áreas de D2 y las 10 actividades de D4' as k, case when (select count(*) from campo.areas_comercial where codigo in ('facturacion', 'cartera_scrr', 'perdidas', 'pqr_atencion')) = 4 and (select count(*) from campo.actividades where codigo in ('suspension', 'corte', 'reconexion', 'lectura', 'reparto', 'revision_previa', 'revision_pqr', 'instalacion_medidor', 'instalacion_acometida', 'posible_perdida')) = 10 then 'OK' else 'FALLA' end as estado
  union all
  select 6 as o, '6 personal_eventos: columna valor y los 7 tipos' as k, case when exists (select 1 from pg_attribute where attrelid = 'campo.personal_eventos'::regclass and attname = 'valor' and not attisdropped) and pg_get_constraintdef((select oid from pg_constraint where conrelid = 'campo.personal_eventos'::regclass and conname = 'personal_eventos_tipo_evento_check')) like '%quitar_actividad%' then 'OK' else 'FALLA' end as estado
  union all
  select 7 as o, '7 permisos: las 6 RPC solo para service_role; tablas sin permisos' as k, case when (select bool_and(has_function_privilege('service_role', f, 'execute') and not has_function_privilege('anon', f, 'execute') and not has_function_privilege('authenticated', f, 'execute')) from unnest(array['public.geoportal_campo_personal_fijar(text,text,text,jsonb,text)', 'public.geoportal_campo_cuadrillas(text,jsonb,text)', 'public.geoportal_campo_cuadrilla_cambiar(text,jsonb,text)', 'public.geoportal_campo_catalogos(text,text)', 'public.geoportal_campo_catalogo_cambiar(text,jsonb,text)', 'public.geoportal_campo_personal_actividad(text,text,text)']) f) and (select bool_and(not has_table_privilege(r, t, 'select')) from unnest(array['campo.areas_comercial', 'campo.actividades', 'campo.catalogo_eventos', 'campo.cuadrillas', 'campo.cuadrilla_eventos']) t, unnest(array['anon', 'authenticated', 'service_role']) r) then 'OK' else 'FALLA' end as estado
  union all
  select 8 as o, '8 ninguna función de campo con DELETE o UPDATE sin WHERE (la regla de redes.f_funciones_sin_where aplicada a campo)' as k, case when (with f as (
    select p.oid::regprocedure::text as funcion, regexp_replace(regexp_replace(lower(p.prosrc), '--[^\n]*', '', 'g'), '\mdo\s+update\M', 'do_update', 'g') as src
      from pg_proc p join pg_language l on l.oid = p.prolang
     where l.lanname in ('plpgsql', 'sql') and p.prokind in ('f', 'p')
       and (p.pronamespace = 'campo'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_campo\_%'))),
  s as (select f.funcion, btrim(regexp_replace(x, '\s+', ' ', 'g')) as st from f, regexp_split_to_table(f.src, ';') x)
  select count(*) from s
   where (s.st ~ '\mdelete\s+from\M' and substring(s.st from '\mdelete\s+from\M.*$') !~ '\mwhere\M')
      or (s.st ~ '\mupdate\s+(only\s+)?[a-z_][a-z0-9_."]*(\s+(as\s+)?[a-z_][a-z0-9_]*)?\s+set\M'
          and substring(s.st from '\mupdate\s+(?:only\s+)?[a-z_][a-z0-9_."]*(?:\s+(?:as\s+)?[a-z_][a-z0-9_]*)?\s+set\M.*$') !~ '\mwhere\M')) = 0 then 'OK' else 'FALLA' end as estado
  union all
  select 9 as o, '9 redes.f_funciones_sin_where() devuelve cero filas' as k, case when (select count(*) from redes.f_funciones_sin_where()) = 0 then 'OK' else 'FALLA' end as estado
) t order by o;
